function SidebarMap({ index, answers, questions, done, lang, L, footerText }) {
  const currentBlock = done ? '' : questions[index]?.block_id;
  const seenBlocks = new Set(questions.slice(0, answers.length).map(question => question?.block_id));
  return <aside className="mt-side mt-side--left" aria-label={L.map}>
    <p className="mt-side-kicker">{L.map}</p>
    <p className="mt-side-title">{L.step} {done ? SESSION_SIZE : index+1}, {SESSION_SIZE} {lang==='ru'?'всего':'tadan'}</p>
    <p className="mt-side-subtitle">{L.question}</p>
    <ol className="mt-step-grid">{Array.from({length:SESSION_SIZE},(_,i) => {
      const state = done || i < answers.length ? L.completed : i === index ? L.current : L.upcoming;
      return <li key={i} className={`${i === index && !done ? 'active' : ''} ${i < answers.length || done ? 'complete' : ''} ${answers[i] ? (answers[i].correct ? 'ok' : 'bad') : ''} ${i > index && !done ? 'locked' : ''}`}
        aria-current={i === index && !done ? 'step' : undefined} aria-label={`${L.question} ${i+1}: ${state}`}>{i+1}{answers[i]?.correct && <IconBadge />}{i > index && !done && <IconLock />}{i === index && !done && <IconFlame />}</li>;
    })}</ol>
    <p className="mt-side-kicker mt-block-heading">{L.tasks}</p>
    <ol className="mt-block-list">{Array.from({length:4},(_,i) => {
      const id = `b0${i+1}`;
      return <li key={id} className={`${id === currentBlock ? 'active' : ''} ${seenBlocks.has(id) ? 'complete' : ''}`}
        aria-label={`${i+1}. ${text(sectionNames[id],lang)}`}>{i+1}</li>;
    })}</ol>
    {!done && <p className="mt-side-bottom">{footerText}</p>}
  </aside>;
}

function SidebarNote({ question, done, correctCount, duration, lang, L, pose, bubble, animKey, medal }) {
  const section = sectionNames[question?.block_id];
  return <aside className="mt-side mt-side--right" aria-label={done ? L.result : L.note}>
    <div className="mt-buddy"><div className="mt-bubble" key={animKey}>{bubble}</div><Mascot pose={pose} animKey={animKey} /></div>
    <p className="mt-side-kicker">{done ? L.result : L.note}</p>
    {done ? <><h2 className="mt-side-title">{L.correct}</h2>
      <div className="mt-score-card"><div className="mt-score-ring" role="img" aria-label={`${Math.round(correctCount / SESSION_SIZE * 100)}%`}>
        <svg viewBox="0 0 100 100" aria-hidden="true"><circle className="mt-score-ring-track" cx="50" cy="50" r="41" pathLength="100" />
          <circle className="mt-score-ring-progress" cx="50" cy="50" r="41" pathLength="100" style={{'--mt-ring-offset':100-Math.round(correctCount / SESSION_SIZE * 100)}} /></svg>
        <span aria-hidden="true">{Math.round(correctCount / SESSION_SIZE * 100)}%</span></div>
        <div className="mt-score-copy"><strong className="mt-score"><CountUp value={correctCount} /> / {SESSION_SIZE}</strong>
          <span className="mt-score-caption">{L.time}: {duration == null ? '—' : `${Math.floor(duration/60)}:${String(duration%60).padStart(2,'0')}`}</span></div></div></>
      : <><div className="mt-note-card">
        <span className="mt-note-label">{L.sectionLabel}</span>
        <strong>{section ? text(section,lang) : L.question}</strong>
        <span className="mt-note-label">{L.topicLabel}</span><p>{text(question?.topic,lang)}</p>
        <small>{L.noteHint}</small>
      </div>
      </>}
    <MedalView {...medal} lang={lang} variant="side" />
  </aside>;
}

function Visual({ value, lang }) {
  value = decodeVisual(value);
  if (!value) return null;
  if (typeof value === 'string') return <div className="mt-visual">{value}</div>;
  if (value.svg) return <figure className="mt-figure" role="img" aria-label={value.svg}>
    <svg viewBox="0 0 200 90" width="200" height="90" aria-hidden="true">
      {value.svg === 'straight' && <line x1="20" y1="70" x2="180" y2="20" stroke="#2563eb" strokeWidth="5" strokeLinecap="round" />}
      {value.svg === 'broken' && <polyline points="20,70 60,20 100,70 140,20 180,70" fill="none" stroke="#2563eb" strokeWidth="5" />}
      {value.svg === 'triangle' && <polygon points="100,10 172,80 28,80" fill="#fde7c8" stroke="#d9822b" strokeWidth="4" />}
      {value.svg === 'rectangle' && <polygon points="35,20 165,20 165,70 35,70" fill="#fde7c8" stroke="#d9822b" strokeWidth="4" />}
    </svg></figure>;
  if (value.table || value.rows) return <table className="mt-table"><tbody>{(value.table || value.rows).map((row,i) =>
    <tr key={i}><th>{text(row[0],lang)}</th><td>{text(row[1],lang)}</td></tr>)}</tbody></table>;
  if (value.type === 'text') return <div className="mt-visual mt-visual--text">{text(value.text,lang)}</div>;
  if (value.type === 'expression') return <div className="mt-visual mt-expression">{value.text}</div>;
  if (value.type === 'sequence') return <div className="mt-sequence" role="img" aria-label={value.values.map(v => v ?? '□').join(', ')}>
    {value.values.map((v,i) => <span key={i}>{v ?? '□'}</span>)}</div>;
  if (value.type === 'number_line') {
    const ticks = Array.from({length:(value.max-value.min)/value.step+1},(_,i) => value.min+i*value.step);
    return <div className="mt-numberline" role="img" aria-label={ticks.join(', ')}>
      <div className="mt-line">{value.mark != null && <i style={{left:`${(value.mark-value.min)/(value.max-value.min)*100}%`}} />}</div>
      <div className="mt-ticks">{ticks.map(n => <span key={n}>{n}</span>)}</div></div>;
  }
  if (value.type === 'grid') return <div className="mt-grid" role="img" aria-label={`${value.rows} × ${value.cols}`} style={{gridTemplateColumns:`repeat(${value.cols}, 16px)`}}>
    {Array.from({length:value.rows*value.cols},(_,i) => <i key={i} />)}</div>;
  if (value.type === 'parts') return <div className="mt-parts" role="img" aria-label={`${value.filled} / ${value.count}`}>
    {Array.from({length:value.count},(_,i) => <i key={i} className={i<value.filled?'filled':''} />)}</div>;
  if (value.type === 'table') return <table className="mt-table"><caption>{text(value.caption,lang)}</caption><tbody>{value.rows.map((row,i) =>
    <tr key={i}><th>{text(row.label,lang)}</th><td>{row.value}</td></tr>)}</tbody></table>;
  if (value.type === 'line_kind') return <div className="mt-figure" role="img" aria-label={value.kind}>
    <svg viewBox="0 0 220 64" width="220" height="64" aria-hidden="true"><defs><marker id="mt-g01-arrow" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto-start-reverse"><path d="M0 0 L8 4 L0 8 Z" fill="#2563eb" /></marker></defs>
      <line x1="20" y1="32" x2="200" y2="32" stroke="#2563eb" strokeWidth="4" markerStart={value.kind==='line'?'url(#mt-g01-arrow)':undefined} markerEnd={value.kind!=='segment'?'url(#mt-g01-arrow)':undefined} />
      {value.kind!=='line' && <circle cx="20" cy="32" r="6" fill="#263346" />}{value.kind==='segment' && <circle cx="200" cy="32" r="6" fill="#263346" />}</svg></div>;
  if (value.type === 'shape') {
    const sides = {triangle:3,square:4,rectangle:4,pentagon:5,hexagon:6}[value.kind];
    const points = value.kind==='rectangle'?'35,25 185,25 185,105 35,105':value.kind==='square'?'65,15 155,15 155,105 65,105':
      Array.from({length:sides},(_,i) => `${110+75*Math.cos(-Math.PI/2+i*Math.PI*2/sides)},${65+50*Math.sin(-Math.PI/2+i*Math.PI*2/sides)}`).join(' ');
    return <figure className="mt-figure" role="img" aria-label={`${sides} ${lang==='ru'?'сторон':'tomon'}`}>
      <svg viewBox="0 0 220 130" width="220" height="130" aria-hidden="true"><polygon points={points} fill="#fde7c8" stroke="#d9822b" strokeWidth="4" /></svg>
      {value.sides?.length>0 && <figcaption>{value.sides.join(' · ')} {lang==='ru'?'см':'sm'}</figcaption>}</figure>;
  }
  if (value.type === 'clock') {
    const hourAngle=(value.hour%12+value.minute/60)*Math.PI/6-Math.PI/2;
    const minuteAngle=value.minute*Math.PI/30-Math.PI/2;
    return <div className="mt-figure" role="img" aria-label={`${value.hour}:${String(value.minute).padStart(2,'0')}`}><svg viewBox="0 0 160 160" width="160" height="160" aria-hidden="true">
      <circle cx="80" cy="80" r="72" fill="white" stroke="#2563eb" strokeWidth="4" />
      {Array.from({length:12},(_,i) => <text key={i} x={80+55*Math.sin((i+1)*Math.PI/6)} y={84-55*Math.cos((i+1)*Math.PI/6)} textAnchor="middle" fontSize="14">{i+1}</text>)}
      <line x1="80" y1="80" x2={80+36*Math.cos(hourAngle)} y2={80+36*Math.sin(hourAngle)} stroke="#263346" strokeWidth="6" />
      <line x1="80" y1="80" x2={80+53*Math.cos(minuteAngle)} y2={80+53*Math.sin(minuteAngle)} stroke="#2563eb" strokeWidth="4" />
    </svg></div>;
  }
  return null;
}

/* MASCOT-DATA-START (scripts/build-grade1-trainer-3d.mjs fills this; sources: assets/mascot/*.webp) */
const MASCOT = {
  point: 'data:image/webp;base64,',
  cheer: 'data:image/webp;base64,',
  star: 'data:image/webp;base64,',
  pencil: 'data:image/webp;base64,',
  book: 'data:image/webp;base64,',
};
/* MASCOT-DATA-END */

let mascotWarm = false;
// Faqat ko'rinish: pose (point | cheer | star | pencil | book) tashqaridan beriladi, animKey o'zgarganda animatsiya qayta o'ynaydi.
function Mascot({ pose, animKey, inline }) {
  useEffect(() => {
    if (mascotWarm) return;
    mascotWarm = true;
    Object.values(MASCOT).forEach(src => { const img = new Image(); img.src = src; if (img.decode) img.decode().catch(() => {}); });
  }, []);
  const anim = pose === 'cheer' ? 'jump' : pose === 'star' ? 'bounce' : pose === 'book' ? 'nod' : 'idle';
  return <span className={inline ? 'mt-mascot mt-mascot--inline' : 'mt-mascot'} aria-hidden="true">
    <span className="mt-mfx" data-anim={anim} key={animKey}><img src={MASCOT[pose] || MASCOT.point} alt="" draggable="false" width="96" height="104" /></span>
  </span>;
}

