let FXLIB = null;
const getFX = () => (FXLIB || (FXLIB = loadFX()));
const reduceMotion = () => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

function makeStarGeometry(THREE) {
  const shape = new THREE.Shape();
  for (let i = 0; i < 10; i++) {
    const r = i % 2 ? 0.45 : 1;
    const a = Math.PI / 2 + (i * Math.PI) / 5;
    if (i === 0) shape.moveTo(Math.cos(a) * r, Math.sin(a) * r); else shape.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.16, bevelEnabled: true, bevelThickness: 0.07, bevelSize: 0.06, bevelSegments: 2 });
  geo.center();
  return geo;
}

// Faqat ko'rinish: javob/natija hodisasida 3D yulduzlar va tangalar sochiladi. Hech narsani o'qimaydi, yozmaydi.
function createFxSystem(host) {
  const { gsap, THREE } = getFX();
  const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: 'low-power' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
  renderer.setClearColor(0x000000, 0);
  host.appendChild(renderer.domElement);
  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(0, 1, 1, 0, -900, 900);
  scene.add(new THREE.AmbientLight(0xffffff, 1.3));
  const key = new THREE.DirectionalLight(0xffffff, 2.6); key.position.set(-300, 400, 500); scene.add(key);
  const rimLight = new THREE.DirectionalLight(0x7fe9ff, 1.4); rimLight.position.set(400, -200, 300); scene.add(rimLight);
  const gold = new THREE.MeshStandardMaterial({ color: 0xffc83d, metalness: 0.55, roughness: 0.3, emissive: 0x8a5200, emissiveIntensity: 0.4 });
  const dark = new THREE.MeshStandardMaterial({ color: 0xd99a12, metalness: 0.6, roughness: 0.4 });
  const starGeo = makeStarGeometry(THREE);
  const coinGeo = new THREE.CylinderGeometry(1, 1, 0.2, 36);
  const rimGeo = new THREE.TorusGeometry(0.8, 0.07, 10, 36);
  const timelines = new Set();
  let W = 1, H = 1, running = false, alive = 0, lost = false;
  const fit = () => {
    const r = host.getBoundingClientRect();
    W = Math.max(1, Math.round(r.width)); H = Math.max(1, Math.round(r.height));
    renderer.setSize(W, H);
    camera.left = 0; camera.right = W; camera.top = H; camera.bottom = 0; camera.updateProjectionMatrix();
  };
  fit();
  const ro = typeof ResizeObserver === 'function' ? new ResizeObserver(fit) : null;
  if (ro) ro.observe(host);
  const render = () => renderer.render(scene, camera);
  const start = () => { if (!running) { running = true; gsap.ticker.add(render); } };
  const stop = () => { if (running) { running = false; gsap.ticker.remove(render); render(); } };
  const onLost = e => { e.preventDefault(); lost = true; };
  renderer.domElement.addEventListener('webglcontextlost', onLost);
  const spawn = obj => { scene.add(obj); alive++; start(); };
  const retire = obj => { scene.remove(obj); alive = Math.max(0, alive - 1); if (alive === 0) stop(); };
  const track = tl => { timelines.add(tl); return tl; };

  const burstStars = (o, big) => {
    const n = (W < 520 ? 7 : 10) + (big ? 5 : 0);
    const oy = H - o.y;
    for (let i = 0; i < n; i++) {
      const m = new THREE.Mesh(starGeo, gold);
      const s = 12 + Math.random() * 10 + (big ? 5 : 0);
      m.scale.setScalar(0.01);
      m.position.set(o.x, oy, (Math.random() - 0.5) * 80);
      m.rotation.set((Math.random() - 0.5) * 0.9, (Math.random() - 0.5) * 0.9, Math.random() * 6);
      spawn(m);
      const a = Math.random() * Math.PI * 2, d = 60 + Math.random() * 100;
      const tl = track(gsap.timeline({ onComplete: () => { timelines.delete(tl); retire(m); } }));
      tl.to(m.scale, { x: s, y: s, z: s, duration: 0.2, ease: 'back.out(3)' }, 0)
        .to(m.position, { x: o.x + Math.cos(a) * d, y: oy + Math.sin(a) * d * 0.8 + 50, duration: 0.7, ease: 'power3.out' }, 0)
        .to(m.position, { y: '-=180', duration: 0.6, ease: 'power2.in' }, 0.7)
        .to(m.rotation, { y: '+=' + (3 + Math.random() * 3), z: '+=' + (Math.random() * 4 - 2), duration: 1.3, ease: 'none' }, 0)
        .to(m.scale, { x: 0.01, y: 0.01, z: 0.01, duration: 0.25, ease: 'power2.in' }, 1.0);
    }
  };

  const shower = () => {
    const n = W < 520 ? 12 : 20;
    for (let i = 0; i < n; i++) {
      const c = new THREE.Group();
      const body = new THREE.Mesh(coinGeo, gold); body.rotation.x = Math.PI / 2; c.add(body);
      const r1 = new THREE.Mesh(rimGeo, dark); r1.position.z = 0.16; c.add(r1);
      const r2 = new THREE.Mesh(rimGeo, dark); r2.position.z = -0.16; c.add(r2);
      c.scale.setScalar(16 + Math.random() * 10);
      const x = Math.random() * W;
      c.position.set(x, H + 40, (Math.random() - 0.5) * 80);
      c.rotation.y = Math.random() * 6;
      spawn(c);
      const tl = track(gsap.timeline({ delay: i * 0.09, onComplete: () => { timelines.delete(tl); retire(c); } }));
      tl.to(c.position, { y: -60, x: x + (Math.random() - 0.5) * 120, duration: 2.1 + Math.random() * 0.8, ease: 'power1.in' }, 0)
        .to(c.rotation, { y: '+=' + (10 + Math.random() * 8), x: '+=' + Math.random() * 2, duration: 3, ease: 'none' }, 0);
    }
  };

  return {
    fire(kind, o) {
      if (lost) return;
      if (kind === 'done') shower(); else burstStars(o, kind === 'streak');
    },
    dispose() {
      timelines.forEach(t => t.kill());
      timelines.clear();
      stop();
      if (ro) ro.disconnect();
      renderer.domElement.removeEventListener('webglcontextlost', onLost);
      starGeo.dispose(); coinGeo.dispose(); rimGeo.dispose(); gold.dispose(); dark.dispose();
      renderer.dispose();
      renderer.domElement.remove();
    },
  };
}

function Fx3D({ type, id }) {
  const host = useRef(null);
  const sys = useRef(null);
  const first = useRef(true);
  useEffect(() => () => { if (sys.current) sys.current.dispose(); sys.current = null; }, []);
  useEffect(() => {
    const isFirst = first.current;
    first.current = false;
    if (!type || type === 'wrong' || (isFirst && type !== 'done') || reduceMotion()) return;
    const el = host.current;
    if (!el) return;
    const box = el.getBoundingClientRect();
    let origin = { x: box.width / 2, y: 0 };
    if (type !== 'done') {
      const opt = el.parentElement && el.parentElement.querySelector('.mt-option.picked');
      if (!opt) return;
      const r = opt.getBoundingClientRect();
      origin = { x: r.left - box.left + r.width / 2, y: r.top - box.top + r.height / 2 };
    }
    try {
      if (!sys.current) sys.current = createFxSystem(el);
      sys.current.fire(type, origin);
    } catch {
      if (sys.current) sys.current.dispose();
      sys.current = null;
    }
  }, [id]); // eslint-disable-line react-hooks/exhaustive-deps
  return <div className="mt-fx3d" ref={host} aria-hidden="true" />;
}

function CssCoin() {
  return <span className="mt-coin" aria-hidden="true"><span className="mt-coin-spin">{[-3,-2,-1,0,1,2,3].map(z => <i key={z} className="mt-coin-edge" style={{transform:`translateZ(${z}px)`}} />)}<i className="mt-coin-face" style={{transform:'translateZ(4px)'}} /><i className="mt-coin-face" style={{transform:'rotateY(180deg) translateZ(4px)'}} /></span></span>;
}

// Natija ekranidagi tanga: Three.js (WebGL bo'lmasa CSS 3D tanga qoladi).
function Coin3D() {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || reduceMotion()) return undefined;
    let teardown = () => {};
    try {
      const { gsap, THREE } = getFX();
      const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: 'low-power' });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.setSize(52, 52);
      renderer.setClearColor(0x000000, 0);
      const scene = new THREE.Scene();
      const camera = new THREE.OrthographicCamera(-1.25, 1.25, 1.25, -1.25, -10, 10);
      scene.add(new THREE.AmbientLight(0xffffff, 1.3));
      const key = new THREE.DirectionalLight(0xffffff, 2.6); key.position.set(-2, 3, 5); scene.add(key);
      const gold = new THREE.MeshStandardMaterial({ color: 0xffc83d, metalness: 0.55, roughness: 0.3, emissive: 0x8a5200, emissiveIntensity: 0.4 });
      const dark = new THREE.MeshStandardMaterial({ color: 0xd99a12, metalness: 0.6, roughness: 0.4 });
      const geo = new THREE.CylinderGeometry(1, 1, 0.3, 36);
      const rimGeo = new THREE.TorusGeometry(0.8, 0.07, 10, 36);
      const g = new THREE.Group();
      const body = new THREE.Mesh(geo, gold); body.rotation.x = Math.PI / 2; g.add(body);
      const r1 = new THREE.Mesh(rimGeo, dark); r1.position.z = 0.16; g.add(r1);
      const r2 = new THREE.Mesh(rimGeo, dark); r2.position.z = -0.16; g.add(r2);
      g.rotation.x = 0.3;
      scene.add(g);
      let visible = true;
      const io = typeof IntersectionObserver === 'function' ? new IntersectionObserver(e => { visible = e[0].isIntersecting; }) : null;
      if (io) io.observe(el);
      const tick = () => { if (!visible) return; g.rotation.y += 0.035; renderer.render(scene, camera); };
      gsap.ticker.add(tick);
      el.appendChild(renderer.domElement);
      el.classList.add('is-gl');
      teardown = () => {
        gsap.ticker.remove(tick);
        if (io) io.disconnect();
        geo.dispose(); rimGeo.dispose(); gold.dispose(); dark.dispose(); renderer.dispose();
        renderer.domElement.remove();
        el.classList.remove('is-gl');
      };
    } catch { teardown(); }
    return () => teardown();
  }, []);
  return <span className="mt-coin3d" ref={ref} aria-hidden="true"><CssCoin /></span>;
}

// Natija sanog'i: 0 dan sanaydi (GSAP). Matn tuguni React'niki, faqat qiymati o'zgaradi.
function CountUp({ value }) {
  const ref = useRef(null);
  useEffect(() => {
    const node = ref.current && ref.current.firstChild;
    if (!node || reduceMotion()) return undefined;
    let tween = null;
    try {
      const { gsap } = getFX();
      const o = { v: 0 };
      node.nodeValue = '0';
      tween = gsap.to(o, { v: value, duration: 0.9, delay: 0.25, ease: 'power2.out', onUpdate: () => { node.nodeValue = String(Math.round(o.v)); } });
    } catch { node.nodeValue = String(value); }
    return () => { if (tween) tween.kill(); node.nodeValue = String(value); };
  }, [value]);
  return <span ref={ref}>{value}</span>;
}

