/* global MedalView, medalLevel, medalNext, streakStats, medalPoly, medalStar, medalRibbons */
// ----- begin shared part: src/components/shared/trainer-parts/medal-view.part.jsx -----
/* eslint-disable no-undef */
// ===== Kombo medallari: umumiy qism (src/components/shared/trainer-parts/medal-view.part.jsx) =====
// Trenajor manbasi buni `/* @include ... */` bilan qo'shadi (scripts/lib/trainer-parts.mjs, build paytida) va o'zining
// `buildMedal(THREE, level)`, `MEDAL_RADIUS`, `MEDAL_FILL` ni beradi. Boshqa sinflar uchun ham shu qism ishlatiladi.
// Faqat ko'rinish: `attempt.answers` dan hosil bo'ladi, javob/ball/urinishga tegmaydi.
// Qoida: 3, 5, 7, 9, 11 ketma-ket to'g'ri javob (kombo) = 1..5-daraja medal; hammasi to'g'ri (SESSION_SIZE) = 6-daraja.
// Kombo buzilsa (xato javob) medal yo'qoladi, kombo qayta yig'ilsa mos medal qaytadan paydo bo'ladi.
const MEDAL_STEPS = [3, 5, 7, 9, 11];

function streakStats(answers) {
  let cur = 0;
  let best = 0;
  answers.forEach(a => {
    if (a && a.correct) { cur++; if (cur > best) best = cur; } else cur = 0;
  });
  return { cur, best };
}

function medalLevel(streak, total) {
  if (total > 0 && streak >= total) return 6;
  let level = 0;
  MEDAL_STEPS.forEach((s, i) => { if (streak >= s) level = i + 1; });
  return level;
}

function medalNext(streak, total) {
  const all = MEDAL_STEPS.concat(total);
  for (let i = 0; i < all.length; i++) if (all[i] > streak) return all[i];
  return total;
}

// Umumiy geometriya yordamchilari (ikkala sinf medallari ishlatadi).
function medalPoly(THREE, pts, depth, bevel, center) {
  const shape = new THREE.Shape();
  pts.forEach((p, i) => { if (i) shape.lineTo(p[0], p[1]); else shape.moveTo(p[0], p[1]); });
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 1 });
  if (center) geo.center();
  return geo;
}

function medalStar(THREE, spikes, outer, inner, depth, bevel) {
  const pts = [];
  for (let i = 0; i < spikes * 2; i++) {
    const r = i % 2 ? inner : outer;
    const a = Math.PI / 2 + (i * Math.PI) / spikes;
    pts.push([Math.cos(a) * r, Math.sin(a) * r]);
  }
  return medalPoly(THREE, pts, depth, bevel, true);
}

// Ikkita lenta (medal orqasida osilib turadi).
function medalRibbons(THREE, material, own) {
  const geo = medalPoly(THREE, [[-0.34, 0], [0.34, 0], [0.34, -1.0], [0, -0.78], [-0.34, -1.0]], 0.05, 0.02, false);
  own.push(geo);
  const g = new THREE.Group();
  [-1, 1].forEach(side => {
    const m = new THREE.Mesh(geo, material);
    m.position.set(side * 0.42, -0.5, -0.2);
    m.rotation.z = side * 0.3;
    g.add(m);
  });
  return g;
}

// 3D medal tizimi: bitta WebGL canvas, bir vaqtda bitta medal. Daraja o'zgarsa eski chiqadi, yangisi paydo bo'ladi.
function createMedalSystem(host) {
  const { gsap, THREE } = getFX();
  const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: 'low-power' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setClearColor(0x000000, 0);
  host.appendChild(renderer.domElement);
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(28, 1, 0.1, 60);
  scene.add(new THREE.AmbientLight(0xffffff, 1.6));
  const key = new THREE.DirectionalLight(0xffffff, 3.4); key.position.set(-3, 4, 6); scene.add(key);
  const fill = new THREE.DirectionalLight(MEDAL_FILL, 1.8); fill.position.set(4, -2, 3); scene.add(fill);
  const sparkGeo = new THREE.OctahedronGeometry(1, 0);
  const sparkMat = new THREE.MeshStandardMaterial({ color: MEDAL_FILL, emissive: MEDAL_FILL, emissiveIntensity: 0.9, flatShading: true });
  const cache = new Map();
  const fading = new Set();
  const calls = new Set();
  const still = reduceMotion();
  const t0 = performance.now();
  let cur = null, running = false, visible = true, lost = false;
  const render = () => renderer.render(scene, camera);
  const fit = () => {
    const r = host.getBoundingClientRect();
    const w = Math.max(1, Math.round(r.width)), h = Math.max(1, Math.round(r.height));
    renderer.setSize(w, h);
    camera.aspect = w / h;
    const half = Math.tan((camera.fov * Math.PI) / 360);
    const dist = Math.max(MEDAL_RADIUS / half, MEDAL_RADIUS / (half * camera.aspect)) * 1.06;
    camera.position.set(0, 0, dist);
    camera.updateProjectionMatrix();
    render();
  };
  fit();
  const ro = typeof ResizeObserver === 'function' ? new ResizeObserver(fit) : null;
  if (ro) ro.observe(host);
  const io = typeof IntersectionObserver === 'function' ? new IntersectionObserver(e => { visible = e[0].isIntersecting; }) : null;
  if (io) io.observe(host);
  const onLost = e => { e.preventDefault(); lost = true; };
  renderer.domElement.addEventListener('webglcontextlost', onLost);

  const tick = () => {
    if (!cur && fading.size === 0) { running = false; gsap.ticker.remove(tick); render(); return; }
    if (!visible) return;
    const t = (performance.now() - t0) / 1000;
    [cur].concat(Array.from(fading)).forEach(e => {
      if (!e) return;
      e.group.rotation.y = Math.sin(t * 1.1) * 0.5;
      e.group.rotation.x = Math.sin(t * 0.8) * 0.06;
      e.group.position.y = e.baseY + Math.sin(t * 2.0) * 0.05;
      if (e.update) e.update(t);
    });
    render();
  };
  const ensureRun = () => {
    if (still) { render(); return; }
    if (!running) { running = true; gsap.ticker.add(tick); }
  };

  const sparkles = () => {
    if (still) return;
    for (let i = 0; i < 9; i++) {
      const m = new THREE.Mesh(sparkGeo, sparkMat);
      const s = 0.05 + Math.random() * 0.06;
      m.scale.setScalar(0.001);
      m.position.set(0, 0.1, 0.4);
      scene.add(m);
      const a = (Math.PI * 2 * i) / 9 + Math.random() * 0.4, d = 1.2 + Math.random() * 0.5;
      const tl = gsap.timeline({ onComplete: () => { calls.delete(tl); scene.remove(m); } });
      calls.add(tl);
      tl.to(m.scale, { x: s, y: s, z: s, duration: 0.15, ease: 'power2.out' }, 0)
        .to(m.position, { x: Math.cos(a) * d, y: 0.1 + Math.sin(a) * d, z: 0.6, duration: 0.7, ease: 'power3.out' }, 0)
        .to(m.rotation, { x: '+=4', y: '+=5', duration: 0.7, ease: 'none' }, 0)
        .to(m.scale, { x: 0.001, y: 0.001, z: 0.001, duration: 0.25, ease: 'power2.in' }, 0.5);
    }
  };

  const enter = level => {
    let e = cache.get(level);
    if (!e) {
      e = buildMedal(THREE, level);
      e.level = level;
      e.outer = new THREE.Group();
      e.outer.add(e.group);
      cache.set(level, e);
    }
    if (e.removeCall) { e.removeCall.kill(); e.removeCall = null; }
    fading.delete(e);
    gsap.killTweensOf([e.outer.scale, e.outer.rotation, e.outer.position]);
    e.outer.position.set(0, 0, 0);
    e.outer.rotation.set(0, still ? 0 : -Math.PI, 0);
    e.outer.scale.setScalar(still ? 1 : 0.001);
    e.group.position.y = e.baseY;
    scene.add(e.outer);
    cur = e;
    if (!still) {
      gsap.to(e.outer.scale, { x: 1, y: 1, z: 1, duration: 0.65, ease: 'back.out(2.4)' });
      gsap.to(e.outer.rotation, { y: 0, duration: 0.75, ease: 'power3.out' });
      sparkles();
    }
  };
  const leave = (e, drop) => {
    fading.add(e);
    const o = e.outer;
    gsap.killTweensOf([o.scale, o.rotation, o.position]);
    if (still) { scene.remove(o); fading.delete(e); return; }
    if (drop) {
      gsap.to(o.rotation, { z: 0.7, duration: 0.45, ease: 'power2.in' });
      gsap.to(o.position, { y: -1.8, duration: 0.45, ease: 'power2.in' });
    }
    gsap.to(o.scale, { x: 0.001, y: 0.001, z: 0.001, duration: drop ? 0.45 : 0.22, ease: 'back.in(2)' });
    e.removeCall = gsap.delayedCall(drop ? 0.5 : 0.25, () => { scene.remove(o); fading.delete(e); e.removeCall = null; });
  };

  return {
    set(level) {
      if (lost) return;
      if ((cur && cur.level === level) || (!cur && !level)) return;
      const prev = cur;
      cur = null;
      if (prev) leave(prev, level === 0);
      if (level) enter(level);
      ensureRun();
    },
    dispose() {
      calls.forEach(t => t.kill()); calls.clear();
      cache.forEach(e => { if (e.removeCall) e.removeCall.kill(); gsap.killTweensOf([e.outer.scale, e.outer.rotation, e.outer.position]); e.own.forEach(o => o.dispose()); });
      cache.clear(); fading.clear(); cur = null;
      if (running) { running = false; gsap.ticker.remove(tick); }
      if (ro) ro.disconnect();
      if (io) io.disconnect();
      renderer.domElement.removeEventListener('webglcontextlost', onLost);
      sparkGeo.dispose(); sparkMat.dispose();
      renderer.dispose();
      renderer.domElement.remove();
    },
  };
}

// Medal joyi: BITTA o'zgarmas o'lchamli div. Medal ko'rinsa ham, yo'qolsa ham div o'lchami o'zgarmaydi, ichidan chiqmaydi (overflow: hidden).
// variant: 'side' (o'ng panel, planshet va desktop) | 'foot' (telefon: "Keyingi" tugmasi yonida). Ko'rinmas joy (display:none) WebGL yaratmaydi.
function MedalView({ level, streak, next, done, lang, variant }) {
  const host = useRef(null);
  const view = useRef(null);
  const levelRef = useRef(level);
  useEffect(() => { levelRef.current = level; if (view.current) view.current.set(level); }, [level]);
  useEffect(() => {
    const el = host.current;
    if (!el) return undefined;
    const sync = () => {
      const r = el.getBoundingClientRect();
      const shown = r.width > 8 && r.height > 8;
      if (shown && !view.current) {
        try { view.current = createMedalSystem(el); view.current.set(levelRef.current); }
        catch { if (view.current) view.current.dispose(); view.current = null; }
      } else if (!shown && view.current) { view.current.dispose(); view.current = null; }
    };
    sync();
    const ro = typeof ResizeObserver === 'function' ? new ResizeObserver(sync) : null;
    if (ro) ro.observe(el);
    return () => { if (ro) ro.disconnect(); if (view.current) view.current.dispose(); view.current = null; };
  }, []);
  const pct = done ? 0 : Math.max(0, Math.min(100, (streak / next) * 100));
  return <div className={`mt-medal-slot mt-medal-slot--${variant}`} data-level={level}>
    <div className="mt-medal-canvas" ref={host} aria-hidden="true" />
    {level > 0 && <span className="mt-medal-flash" key={`f${level}`} aria-hidden="true" />}
    {level > 0 && <span className="mt-medal-count" key={`c${streak}`} aria-hidden="true">×{streak}</span>}
    {level > 0 && <span className="mt-sr" role="status">{lang === 'ru' ? 'Комбо' : 'Kombo'} ×{streak}</span>}
    {!done && <span className="mt-medal-bar" aria-hidden="true"><i style={{ width: `${pct}%` }} /></span>}
  </div>;
}
// ----- end shared part -----
// 1-sinf medallari: neon "gamer" medallar (jilolangan metall + yonib turuvchi emblema). Har daraja o'z shakli va bezagiga ega:
// 3 bronza olti burchak, 5 kumush sakkiz burchak, 7 oltin qanotli, 9 feruza qanotli gavhar, 11 binafsha toj va qanot, 15 afsonaviy kamalak medal.
// eslint-disable-next-line no-unused-vars
const MEDAL_RADIUS = 1.95;
// eslint-disable-next-line no-unused-vars
const MEDAL_FILL = 0x6fe8ff;
const G1_MEDALS = [
  { sides: 6, metal: 0xcd7f32, plate: 0x8a4f1d, glow: 0xff9a2e, emblem: 'star', ribbon: 0xff6a4d, wings: false, crown: false, halo: false },
  { sides: 8, metal: 0xcfd8ea, plate: 0x7b88a8, glow: 0x6fe8ff, emblem: 'bolt', ribbon: 0x3d6bff, wings: false, crown: false, halo: false },
  { sides: 48, metal: 0xffc83d, plate: 0xb87a00, glow: 0xffe36b, emblem: 'star', ribbon: 0xff4f28, wings: true, crown: false, halo: false },
  { sides: 6, metal: 0x4af2d0, plate: 0x0f8f7a, glow: 0x9dfff0, emblem: 'gem', ribbon: 0x1f8fff, wings: true, crown: false, halo: false },
  { sides: 8, metal: 0xb36bff, plate: 0x5a2aa8, glow: 0xff8fd8, emblem: 'gem', ribbon: 0xff4fa0, wings: true, crown: true, halo: false },
  { sides: 48, metal: 0xffd75e, plate: 0xc98f08, glow: 0xffffff, emblem: 'crown', ribbon: 0xff4f28, wings: true, crown: true, halo: true, legend: true },
];

// eslint-disable-next-line no-unused-vars
function buildMedal(THREE, lvl) {
  const s = G1_MEDALS[lvl - 1];
  const own = [];
  const mat = opt => { const m = new THREE.MeshStandardMaterial(opt); own.push(m); return m; };
  const geo = g => { own.push(g); return g; };
  const group = new THREE.Group();
  const metal = mat({ color: s.metal, metalness: 0.5, roughness: 0.32, emissive: s.metal, emissiveIntensity: 0.22 });
  const plate = mat({ color: s.plate, metalness: 0.3, roughness: 0.5, emissive: s.glow, emissiveIntensity: 0.16 });
  const glow = mat({ color: s.glow, emissive: s.glow, emissiveIntensity: 0.9, metalness: 0.2, roughness: 0.35, flatShading: s.emblem === 'gem' });
  const gold = mat({ color: 0xffc83d, metalness: 0.5, roughness: 0.3, emissive: 0xffa000, emissiveIntensity: 0.3 });
  const ribbonMat = mat({ color: s.ribbon, metalness: 0.2, roughness: 0.6 });

  group.add(medalRibbons(THREE, ribbonMat, own));
  const base = new THREE.Mesh(geo(new THREE.CylinderGeometry(1, 1, 0.24, s.sides)), metal);
  base.rotation.x = Math.PI / 2;
  group.add(base);
  const rim = new THREE.Mesh(geo(new THREE.TorusGeometry(1, 0.075, 10, s.sides)), metal);
  rim.rotation.z = -Math.PI / 2; rim.position.z = 0.12;
  group.add(rim);
  const face = new THREE.Mesh(geo(new THREE.CylinderGeometry(0.78, 0.78, 0.06, s.sides)), plate);
  face.rotation.x = Math.PI / 2; face.position.z = 0.14;
  group.add(face);
  const inner = new THREE.Mesh(geo(new THREE.TorusGeometry(0.8, 0.03, 8, 64)), glow);
  inner.position.z = 0.18;
  group.add(inner);

  let emblem;
  if (s.emblem === 'star') emblem = new THREE.Mesh(geo(medalStar(THREE, 5, 0.56, 0.24, 0.1, 0.03)), glow);
  else if (s.emblem === 'bolt') emblem = new THREE.Mesh(geo(medalPoly(THREE, [[-0.14, 0.55], [0.26, 0.55], [0.06, 0.12], [0.3, 0.12], [-0.2, -0.58], [-0.06, -0.06], [-0.3, -0.06]], 0.1, 0.03, true)), glow);
  else if (s.emblem === 'crown') emblem = new THREE.Mesh(geo(medalPoly(THREE, [[-0.46, -0.26], [-0.46, 0.26], [-0.23, 0.02], [0, 0.38], [0.23, 0.02], [0.46, 0.26], [0.46, -0.26]], 0.1, 0.03, true)), glow);
  else { emblem = new THREE.Mesh(geo(new THREE.OctahedronGeometry(0.38, 0)), glow); emblem.scale.set(1, 1.35, 0.8); }
  emblem.position.z = 0.26;
  group.add(emblem);

  if (s.wings) {
    const right = [[1, 0.35], [1.78, 0.8], [1.58, 0.28], [1.98, 0.2], [1.5, -0.1], [1.7, -0.48], [1, -0.22]];
    const left = right.map(p => [-p[0], p[1]]).reverse();
    [right, left].forEach(pts => {
      const w = new THREE.Mesh(geo(medalPoly(THREE, pts, 0.06, 0.02, false)), metal);
      w.position.z = -0.05;
      group.add(w);
    });
  }
  if (s.crown) {
    const crown = new THREE.Mesh(geo(medalPoly(THREE, [[-0.42, 0], [-0.42, 0.36], [-0.21, 0.16], [0, 0.52], [0.21, 0.16], [0.42, 0.36], [0.42, 0]], 0.1, 0.03, false)), gold);
    crown.position.set(0, 1.02, 0);
    group.add(crown);
  }
  let halo = null;
  if (s.halo) {
    halo = new THREE.Mesh(geo(new THREE.TorusGeometry(1.55, 0.035, 8, 72)), glow);
    halo.position.z = -0.08;
    group.add(halo);
  }
  const update = t => {
    if (halo) halo.rotation.z = t * 0.6;
    glow.emissiveIntensity = 0.75 + Math.sin(t * 3) * 0.2;
    if (s.legend) {
      const h = (t * 0.15) % 1;
      glow.emissive.setHSL(h, 1, 0.55);
      glow.color.setHSL(h, 1, 0.6);
    }
  };
  return { group, own, update, baseY: s.crown ? 0.02 : 0.15 };
}

const SESSION_SIZE = 15;
const VISUAL_PREFIX = '@g01vis:';

function decodeVisual(value) {
  if (typeof value !== 'string' || !value.startsWith(VISUAL_PREFIX)) return value;
  try {
    const data = JSON.parse(value.slice(VISUAL_PREFIX.length));
    if (Array.isArray(data) && data[0] === 'table' && Array.isArray(data[2])) {
      return { type: 'table', rows: data[2].map(([label, cellValue]) => ({ label, value: cellValue })), caption: data[1] };
    }
    return data && typeof data === 'object' && !Array.isArray(data) ? data : value;
  } catch {
    return value;
  }
}

// Katta grafikli savol (ko'p qatorli nuqtalar, shakl, soat, jadval, rasm): savol va grafik yonma-yon turadi, ustma-ust emas
// (aks holda grafik sahifani skrollga majbur qiladi). Matn, ifoda, sonlar qatori, son o'qi va kichik vizuallar oldingidek.
function isSplitVisual(raw) {
  const v = decodeVisual(raw);
  if (!v || typeof v !== 'object') return false;
  if (v.svg || v.table || v.rows) return true;
  if (v.type === 'grid') return Number(v.rows) >= 4;
  return v.type === 'shape' || v.type === 'clock' || v.type === 'table';
}

// Skrollsizlik: ramkaning pastida bo'sh joy qolmasin. Katta ekranda 6 px (yon chetlar bilan bir xil), planshet va telefonda 0;
// LMS konteynerlarining pastki padding/margin/border i qo'shiladi (ular bo'lsa sahifa skroll qilmaydi).
function frameBottomSpace(root) {
  let space = window.innerWidth >= 1200 ? 6 : 0;
  for (let el = root.parentElement; el && el !== document.documentElement; el = el.parentElement) {
    const cs = window.getComputedStyle(el);
    space += (Number.parseFloat(cs.paddingBottom) || 0) + (Number.parseFloat(cs.marginBottom) || 0) + (Number.parseFloat(cs.borderBottomWidth) || 0);
  }
  return space;
}

// Sahifa kengligi/balandligi o'zgarsa (masalan, javobdan keyin vertikal skroll chizig'i paydo bo'lsa) --mt-sbw va balandlikni qayta o'lchaydi:
// aks holda 100vw ramka skroll chizig'i kengligiga chiqib, gorizontal skroll hosil qiladi.
function watchPage(measure) {
  if (typeof ResizeObserver !== 'function') return () => {};
  let frame = 0;
  const ro = new ResizeObserver(() => { window.cancelAnimationFrame(frame); frame = window.requestAnimationFrame(measure); });
  ro.observe(document.documentElement);
  return () => { window.cancelAnimationFrame(frame); ro.disconnect(); };
}

function attemptProblem(attempt) {
  if (!attempt) return { code: 'missingAttempt' };
  if (attempt.question_count !== SESSION_SIZE) return { code: 'wrongCount', actual: attempt.question_count };
  if (!Array.isArray(attempt.answers) || attempt.answers.length > SESSION_SIZE ||
      (attempt.status === 'finished' && attempt.answers.length !== SESSION_SIZE)) {
    return { code: 'invalidAnswers', actual: attempt.answers?.length };
  }
  const visibleCount = attempt.status === 'finished' ? SESSION_SIZE : Math.min(SESSION_SIZE, attempt.answers.length + 1);
  if (!Array.isArray(attempt.questions) || attempt.questions.length < visibleCount ||
      attempt.questions.length > SESSION_SIZE) {
    return { code: 'missingQuestions', actual: attempt.questions?.length };
  }
  const ids = new Set();
  for (const [index, question] of attempt.questions.entries()) {
    if (!question || typeof question.question_id !== 'string' || !question.question_id ||
        typeof question.block_id !== 'string' || !question.block_id || !Array.isArray(question.options) ||
        question.options.length < 2 || question.options.length > 4 ||
        !question.options.every(option => option && typeof option.id === 'string' && option.id)) {
      return { code: 'invalidQuestion', id: question?.question_id };
    }
    if (Number(question.grade) !== 1) return { code: 'wrongGrade', id: question.question_id };
    if (ids.has(question.question_id)) return { code: 'duplicateQuestions', id: question.question_id };
    const optionIds = question.options.map(option => option.id);
    if (new Set(optionIds).size !== optionIds.length ||
        ((index < attempt.answers.length || question.correct_answer != null) && !optionIds.includes(question.correct_answer))) {
      return { code: 'invalidQuestion', id: question.question_id };
    }
    ids.add(question.question_id);
  }
  return null;
}

function firstQuestionDetails(attempt) {
  const question = Array.isArray(attempt?.questions) ? attempt.questions[0] : null;
  if (!question) return '';
  const field = key => String(question[key] ?? '—');
  return `question_id=${field('question_id')} · grade=${field('grade')} · block_id=${field('block_id')} · lesson=${field('lesson')} · status=${field('status')}`;
}

function parseLmsDate(value) {
  if (typeof value !== 'string') return NaN;
  const iso = value.replace(' ', 'T');
  return Date.parse(/(?:Z|[+-]\d\d:\d\d)$/.test(iso) ? iso : `${iso}+05:00`);
}

function TrainerBody({ attempt, lang = 'uz', busy = false, onAnswer, onFinished, onRestart, onExit }) {
  const L = labels[lang] || labels.uz;
  const questions = Array.isArray(attempt?.questions) ? attempt.questions : [];
  const answers = Array.isArray(attempt?.answers) ? attempt.answers : [];
  const problem = attemptProblem(attempt);
  const invalid = problem !== null;
  const diagnostic = problem && `${L[problem.code]}${problem.actual == null ? '' : ` (${problem.actual}/${SESSION_SIZE})`}${problem.id ? `: ${problem.id}` : ''}.`;
  const receivedQuestion = problem?.code === 'missingQuestions' ? firstQuestionDetails(attempt) : '';
  const attemptKey = `${attempt?.started_at || ''}|${questions.map(question => question?.question_id).join(',')}`;
  const [index,setIndex] = useState(Math.max(0,answers.length-1));
  const [actionError,setActionError] = useState('');
  const heading = useRef(null);
  const trainerRoot = useRef(null);
  const pendingAnswer = useRef(null);
  const pendingFinish = useRef(false);
  const finishSawBusy = useRef(false);
  const q = questions[index];
  const answer = answers[index];
  const done = attempt?.status === 'finished';
  const hasRestart = typeof onRestart === 'function';
  const hasExit = typeof onExit === 'function';
  useEffect(() => {
    const measure = () => {
      const root = trainerRoot.current;
      if (!root) return;
      const externalRetry = done && !hasRestart && root.nextElementSibling?.tagName === 'BUTTON' ? root.nextElementSibling : null;
      const bottomSpace = externalRetry ? Math.max(20,
        externalRetry.getBoundingClientRect().height +
        (Number.parseFloat(window.getComputedStyle(externalRetry).marginTop) || 0) +
        (Number.parseFloat(window.getComputedStyle(root.parentElement).paddingBottom) || 0)) : frameBottomSpace(root);
      const available = Math.max(0, Math.floor(window.innerHeight - Math.max(0,root.getBoundingClientRect().top + window.scrollY) - bottomSpace));
      root.style.setProperty('--mt-available-height',`${available}px`);
      root.style.setProperty('--mt-sbw', `${Math.max(0, window.innerWidth - document.documentElement.clientWidth)}px`);
    };
    const frame = window.requestAnimationFrame(measure);
    window.addEventListener('resize',measure);
    const unwatch = watchPage(measure);
    return () => { window.cancelAnimationFrame(frame); window.removeEventListener('resize',measure); unwatch(); };
  }, [done,hasRestart]);
  useEffect(() => {
    setIndex(Math.max(0,answers.length-1));
    pendingAnswer.current = null;
    pendingFinish.current = false;
    finishSawBusy.current = false;
    setActionError('');
  }, [attemptKey,answers.length]);
  useEffect(() => { if (answer || busy) pendingAnswer.current = null; }, [answer,busy]);
  useEffect(() => {
    if (pendingFinish.current && busy) finishSawBusy.current = true;
    else if (pendingFinish.current && finishSawBusy.current && !done) {
      pendingFinish.current = false;
      finishSawBusy.current = false;
    }
  }, [busy,done]);
  useEffect(() => { heading.current?.focus(); }, [index,done,invalid]);
  const choose = (optionId) => {
    if (invalid || done || busy || answer || !q || pendingAnswer.current === q.question_id) return;
    if (typeof onAnswer !== 'function') { setActionError(L.sendError); return; }
    pendingAnswer.current = q.question_id;
    setActionError('');
    try {
      const result = onAnswer(q.question_id,optionId);
      if (result && typeof result.catch === 'function') result.catch(() => {
        pendingAnswer.current = null;
        setActionError(L.sendError);
      });
    } catch {
      pendingAnswer.current = null;
      setActionError(L.sendError);
    }
  };
  const next = () => {
    if (invalid || done || !answer || busy) return;
    if (index + 1 === SESSION_SIZE) {
      if (pendingFinish.current) return;
      if (typeof onFinished !== 'function') { setActionError(L.sendError); return; }
      pendingFinish.current = true;
      setActionError('');
      try {
        const result = onFinished();
        if (result && typeof result.catch === 'function') result.catch(() => {
          pendingFinish.current = false;
          setActionError(L.sendError);
        });
      } catch {
        pendingFinish.current = false;
        setActionError(L.sendError);
      }
    } else setIndex(index + 1);
  };
  useEffect(() => {
    const key = (event) => {
      if (invalid || busy || done || event.repeat || ['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)) return;
      if (/^[1-4]$/.test(event.key) && !answer) {
        const option = q?.options[Number(event.key)-1];
        if (option) { event.preventDefault(); choose(option.id); }
      } else if (event.key === 'Enter' && answer) { event.preventDefault(); next(); }
    };
    window.addEventListener('keydown',key);
    return () => window.removeEventListener('keydown',key);
  });
  const sections = {};
  answers.forEach((a,i) => {
    const section = questions[i]?.block_id;
    if (!section) return;
    if (!sections[section]) sections[section] = {correct:0,total:0,grade:questions[i].grade};
    sections[section].total++;
    if (a.correct) sections[section].correct++;
  });
  const elapsed = (parseLmsDate(attempt?.finished_at || attempt?.started_at) - parseLmsDate(attempt?.started_at))/1000;
  const duration = Number.isFinite(elapsed) ? Math.max(0,Math.round(elapsed)) : null;
  const correctCount = Number.isInteger(attempt?.correct_count) && attempt.correct_count >= 0 &&
    attempt.correct_count <= SESSION_SIZE ? attempt.correct_count : answers.filter(a => a?.correct).length;
  const showSides = !invalid && (done || !!q);
  const sideFooter = attempt?.kind === 'practice' ? L.practice : `${attempt?.coins_per_correct} ${L.coins} + ${attempt?.points_per_correct} ${L.points}`;
  let streak = 0;
  for (let k = answers.length - 1; k >= 0 && answers[k]?.correct; k--) streak++;
  const pose = done ? (correctCount / SESSION_SIZE >= 0.5 ? 'star' : 'pencil')
    : answer ? (answer.correct ? (streak >= 3 ? 'star' : 'cheer') : 'book') : (index % 2 ? 'point' : 'pencil');
  const bubble = done ? L.bubbleDone : answer ? (answer.correct ? L.bubbleRight : L.bubbleWrong) : busy ? L.saving : L.bubbleIdle;
  const animKey = `${pose}-${answers.length}-${done ? 1 : 0}`;
  const fxType = done ? (correctCount / SESSION_SIZE >= 0.5 ? 'done' : '') : answer ? (answer.correct ? (streak >= 3 ? 'streak' : 'right') : 'wrong') : '';
  const fxId = `${answers.length}-${done ? 1 : 0}`;
  const mst = streakStats(answers);
  const mStreak = done ? mst.best : mst.cur;
  const medal = { level: medalLevel(mStreak, SESSION_SIZE), streak: mStreak, next: medalNext(mStreak, SESSION_SIZE), done };
  return <div ref={trainerRoot} className={done ? 'math-trainer math-trainer--result' : 'math-trainer'}>
    <style>{TRAINER_CSS}</style>
    <div className={showSides ? 'mt-layout' : 'mt-layout mt-layout--plain'} data-exit={typeof onExit === 'function' ? '1' : undefined}>
    <ExitButton onExit={onExit} label={L.exit} />
    <Fx3D type={fxType} id={fxId} />
    {showSides && <SidebarMap index={index} answers={answers} questions={questions} done={done} lang={lang} L={L} footerText={sideFooter} />}
    <div className={done ? 'mt-workspace mt-workspace--result' : 'mt-workspace'}>
    {done && !invalid && correctCount / SESSION_SIZE >= 0.4 && <div className="mt-confetti" aria-hidden="true">{Array.from({length:24},(_,k) => <i key={k} />)}</div>}
    <section className={done ? 'mt-card mt-card--result' : 'mt-card'} aria-label={done ? L.result : L.question}>
      <div className="mt-inner">
        {invalid ? <div className="mt-error" role="alert"><p>{diagnostic}</p>
          {receivedQuestion && <p className="mt-muted">{L.qaDetails}: {receivedQuestion}</p>}</div> : done ? <>
          <div className="mt-header"><div className="mt-header-row"><span className="mt-header-label">{L.result}</span><span className="mt-header-count">{SESSION_SIZE} <span>/ {SESSION_SIZE}</span></span></div>
            <div className="mt-track" role="progressbar" aria-valuemin={0} aria-valuemax={SESSION_SIZE} aria-valuenow={SESSION_SIZE}><span style={{width:'100%'}} /></div></div>
          <div className="mt-result-main"><div className="mt-score-inline" role="status"><strong><CountUp value={correctCount} /> / {SESSION_SIZE}</strong><span>{Math.round(correctCount / SESSION_SIZE * 100)}%</span><span>{L.time}: {duration == null ? '—' : `${Math.floor(duration/60)}:${String(duration%60).padStart(2,'0')}`}</span></div><div className="mt-result-details"><div className="mt-qrow"><Mascot pose={pose} animKey={animKey} inline /><h1 className="mt-title" ref={heading} tabIndex={-1}>{L.sections}</h1></div><table className="mt-table"><tbody>{Object.entries(sections).map(([id,s],i) =>
              <tr key={id}><th><span className="mt-section-name">{Number(s.grade)===1 && sectionNames[id] ? text(sectionNames[id],lang) : `${lang==='ru'?'Раздел':'Bo‘lim'} ${i+1}`}</span><span className="mt-section-track" aria-hidden="true"><span style={{width:`${s.total ? s.correct / s.total * 100 : 0}%`}} /></span></th><td>{s.correct} / {s.total}</td></tr>)}</tbody></table></div>
            <div className="mt-reward" role="status">{attempt.reward
              ? <><div className="mt-reward-head"><Coin3D /><span className="mt-reward-title">{L.reward}</span></div><div className="mt-reward-stats"><div className="mt-stat"><b>{attempt.reward.coins}</b><span>{L.coins}</span></div><div className="mt-stat"><b>{attempt.reward.points}</b><span>{L.points}</span></div></div><p className="mt-muted mt-reward-date"><span>{L.date}</span><b>{attempt.reward_date}</b></p></>
              : L.practice}</div>
            </div>
          {(hasRestart || hasExit) && <div className="mt-footer"><div className="mt-divider" /><div className="mt-actions"><MedalView {...medal} lang={lang} variant="foot" />{hasExit && <button type="button" className="mt-next mt-leave" onClick={() => onExit()}>{L.leave}</button>}{hasRestart && <button type="button" className="mt-next" disabled={busy} onClick={() => onRestart()}>{L.restart}</button>}</div></div>}
        </> : q && <>
          <div className="mt-header"><div className="mt-header-row"><span className="mt-header-label">{L.question}</span><span className="mt-header-count">{String(index+1).padStart(2,'0')} <span>/ {SESSION_SIZE}</span></span></div>
            <div className="mt-track" role="progressbar" aria-valuemin={0} aria-valuemax={SESSION_SIZE} aria-valuenow={index}><span style={{width:`${(index / SESSION_SIZE)*100}%`}} /></div></div>
          <div className="mt-main" key={q.question_id}><div className={`mt-lead${isSplitVisual(q.vis) ? ' mt-lead--split' : ''}${q.vis ? '' : ' mt-lead--novis'}`}><div className="mt-lead-text"><p className="mt-meta">{attempt.kind === 'practice' ? L.practice : `${attempt.coins_per_correct} ${L.coins} + ${attempt.points_per_correct} ${L.points}`}</p>
            {(lang==='uz' || typeof q.topic==='object') && <p className="mt-topic">{text(q.topic,lang)}</p>}
            <div className="mt-qrow"><Mascot pose={pose} animKey={animKey} inline /><h1 className="mt-title" ref={heading} tabIndex={-1}>{text(q.question_text,lang)}</h1></div>
            </div><div className="mt-stage"><Visual value={q.vis} lang={lang} /></div></div>
            <p className="mt-prompt">{L.choose}:</p>
            <div className="mt-options" data-count={q.options.length}>{q.options.map((option,i) =>
              <button key={option.id} type="button" disabled={busy || !!answer}
                aria-label={`${i+1}. ${text(option.text,lang)}`}
                className={`mt-option ${answer && option.id === q.correct_answer ? 'right' : answer?.option_id === option.id ? 'wrong' : ''}${answer?.option_id === option.id ? ' picked' : ''}`}
                onClick={() => choose(option.id)}><span className="mt-option-key" aria-hidden="true">{String.fromCharCode(65+i)}</span><span className="mt-option-text">{text(option.text,lang)}</span>
                {answer && option.id === q.correct_answer && <svg className="mt-option-mark mt-mark-ok" viewBox="0 0 28 28" aria-hidden="true"><path d="M5 15 L12 21 L23 8" /></svg>}
                {answer && option.id === q.correct_answer && answer.option_id === option.id && <span className="mt-burst" aria-hidden="true">{Array.from({length:12},(_,k) => <i key={k} />)}</span>}
                {answer && !answer.correct && answer.option_id === option.id && <svg className="mt-option-mark mt-mark-bad" viewBox="0 0 28 28" aria-hidden="true"><path d="M7 7 L21 21 M21 7 L7 21" /></svg>}</button>)}</div>
            {answer && <div className={`mt-feedback ${answer.correct ? 'mt-feedback--correct' : ''}`} role="status"><strong>{answer.correct ? L.right : L.wrong}</strong>
              <p>{L.explanation}: {text(q.solution_explanation,lang)}</p><small>{L.saved}</small></div>}
            {actionError && <p className="mt-error" role="alert">{actionError}</p>}
            {!answer && <p className="mt-muted mt-hint">{L.hint}</p>}</div>
          <div className="mt-footer"><div className="mt-divider" /><div className="mt-actions"><MedalView {...medal} lang={lang} variant="foot" /><div className="mt-foot-buddy" aria-hidden="true"><Mascot pose={pose} animKey={animKey} /></div><button type="button" className="mt-next" disabled={!answer || busy} onClick={next}>
            {busy ? L.saving : index+1 === SESSION_SIZE ? L.finish : L.next}</button></div></div>
        </>}
      </div>
    </section>
    </div>
    {showSides && <SidebarNote question={q} done={done} correctCount={correctCount} duration={duration} lang={lang} L={L} pose={pose} bubble={bubble} animKey={animKey} medal={medal} />}
    </div>
  </div>;
}

// Eksport qilinadigan komponent: yangi urinishda avval kirish oynasi, keyin trenajor. Urinish mantig'i TrainerBody da, o'zgarmagan.
export default function MathTrainer({ attempt, lang = 'uz', busy = false, onAnswer, onFinished, onRestart, onExit }) {
  const fresh = !!attempt && attempt.status !== 'finished' && Array.isArray(attempt.answers) && attempt.answers.length === 0 && attemptProblem(attempt) === null;
  const [started, setStarted] = useState(!fresh);
  if (fresh && !started) return <TrainerIntro attempt={attempt} lang={lang} onStart={() => setStarted(true)} onExit={onExit} />;
  return <TrainerBody attempt={attempt} lang={lang} busy={busy} onAnswer={onAnswer} onFinished={onFinished} onRestart={onRestart} onExit={onExit} />;
}
